parameters.jsCode:
const parts =
  $json.candidates?.[0]?.content?.parts ?? [];

const rawText = parts
  .filter(part => typeof part.text === 'string')
  .map(part => part.text)
  .join('')
  .trim();

if (!rawText) {
  throw new Error('EVIDENCE_RESPONSE_EMPTY');
}

const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `EVIDENCE_JSON_INVALID: ${error.message}`
  );
}

if (!Array.isArray(parsed.evidence)) {
  throw new Error('EVIDENCE_ARRAY_MISSING');
}

for (const item of parsed.evidence) {
  if (
    typeof item.claim !== 'string' ||
    typeof item.source_url !== 'string'
  ) {
    throw new Error('EVIDENCE_ITEM_INVALID');
  }

  if (!/^https:\/\//i.test(item.source_url)) {
    throw new Error('EVIDENCE_SOURCE_URL_INVALID');
  }
}

return [
  {
    json: {
      recipient_id: $('CONFIGURE - Load Recipient and Candidate Context').item.json.id,
      evidence: parsed.evidence
    }
  }
];

const evidenceData = $json;

const context = $('CONFIGURE - Load Recipient and Candidate Context')
  .item
  .json;

const objectKey = String(context.base_cv_object_key ?? '').trim();

if (!objectKey) {
  throw new Error('base_cv_object_key is missing from candidate context');
}

const supabaseUrl = String($env.SUPABASE_URL ?? '').replace(/\/$/, '');

if (!supabaseUrl) {
  throw new Error('SUPABASE_URL is missing');
}

const bucket = 'Documents';

const encodedKey = objectKey
  .split('/')
  .map(part => encodeURIComponent(part))
  .join('/');

const cvUrl =
  `${supabaseUrl}/storage/v1/object/authenticated/${bucket}/${encodedKey}`;

return [
  {
    json: {
      ...context,
      ...evidenceData,
      cv_url: cvUrl
    }
  }
];

const rawText = String($json.text || '')
  .replace(/\r\n/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (rawText.length < 300) {
  throw new Error('Extracted CV text is too short or unreadable');
}

const maxCharacters = 30000;

return [
  {
    json: {
      ...$('Build Supabase CV URL').item.json,
      cv_text: rawText.slice(0, maxCharacters),
      cv_text_truncated: rawText.length > maxCharacters
    }
  }
];

