const parts =
  $json.candidates?.[0]?.content?.parts ?? [];

const rawText = parts
  .map(part => String(part.text ?? ''))
  .join('')
  .trim();

const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let draft;

try {
  draft = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Gemini draft is not valid JSON: ${error.message}`);
}

const requiredFields = [
  'subject',
  'html_body',
  'cv_summary',
  'professor_claims',
  'candidate_claims'
];

for (const field of requiredFields) {
  if (draft[field] === undefined) {
    throw new Error(`Missing required field: ${field}`);
  }
}

return [
  {
    json: {
      ...$('Parse CV Structure').item.json,
      ...draft
    }
  }


];

const map = { '\\': '\\textbackslash{}', '&': '\\&', '%': '\\%', '$': '\\$', '#': '\\#', '_': '\\_', '{': '\\{', '}': '\\}', '~': '\\textasciitilde{}', '^': '\\textasciicircum{}' };
const esc = v => String(v ?? '').replace(/[\\&%$#_{}~^]/g, ch => map[ch]);

const cv = $json.cv_data ?? {};
const summary = String($json.cv_summary ?? '').trim();
if (!cv.name) throw new Error('CV_DATA_MISSING_NAME');
if (!summary) throw new Error('CV_SUMMARY_EMPTY');

const list = items => (items ?? []).length
  ? '\\begin{itemize}\\setlength{\\itemsep}{1pt}\\setlength{\\topsep}{2pt}\n' + items.map(i => '\\item ' + esc(i)).join('\n') + '\n\\end{itemize}\n'
  : '';
const head = (left, right) => '\\textbf{' + esc(left) + '}' + (right ? '\\hfill ' + esc(right) : '');
const section = (title, body) => body.trim() ? '\\section*{' + title + '}\\vspace{-6pt}\\hrule\\vspace{4pt}\n' + body + '\n' : '';

const education = (cv.education ?? []).map(e => head(e.institution, e.dates) + '\\\\\n' + esc(e.degree) + '\n' + list(e.details)).join('\\medskip\n');
const experience = (cv.experience ?? []).map(x => head(x.organization, x.dates) + '\\\\\n\\textit{' + esc(x.role) + '}\n' + list(x.bullets)).join('\\medskip\n');
const projects = (cv.projects ?? []).map(p => head(p.name, p.context) + '\n' + list(p.bullets)).join('\\medskip\n');
const skills = (cv.skills ?? []).map(s => '\\textbf{' + esc(s.category) + ':} ' + esc(s.items)).join('\\\\\n');
const contact = [cv.location, cv.phone, cv.email, ...(cv.links ?? [])].filter(Boolean).map(esc).join(' \\quad|\\quad ');

const tex =
  '\\documentclass[10pt]{article}\n\\usepackage[margin=0.8in]{geometry}\n\\usepackage{hyperref}\n' +
  '\\pagestyle{empty}\n\\setlength{\\parindent}{0pt}\n\\begin{document}\n' +
  '\\begin{center}{\\LARGE \\textbf{' + esc(cv.name) + '}}\\\\[4pt]' + contact + '\\end{center}\n' +
  section('SUMMARY', esc(summary)) +
  section('EDUCATION', education) +
  section('EXPERIENCE', experience) +
  section('PROJECTS AND RESEARCH', projects) +
  section('PUBLICATIONS', list(cv.publications)) +
  section('SKILLS', skills) +
  section('ACHIEVEMENTS', list(cv.achievements)) +
  '\\end{document}\n';

return [{ json: { ...$json, template_version: 'cv-template-v2', tailored_cv: tex } }];

const c = $json.candidates?.[0];
const text = (c?.content?.parts ?? []).filter(p => !p.thought).map(p => String(p.text ?? '')).join('').trim();
if (!text) throw new Error(`CV_STRUCTURE_EMPTY (finishReason=${c?.finishReason ?? 'NO_CANDIDATE'})`);
if (c?.finishReason === 'MAX_TOKENS') throw new Error('CV_STRUCTURE_TRUNCATED');

let cv;
try { cv = JSON.parse(text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim()); }
catch (e) { throw new Error('CV_STRUCTURE_JSON_INVALID: ' + e.message); }
if (!cv.name) throw new Error('CV_STRUCTURE_NAME_MISSING');

const base = $('Code in JavaScript').item.json;
const src = String(base.cv_text).toLowerCase().replace(/\s+/g, ' ');
const mustExist = [cv.name, ...(cv.education ?? []).map(e => e.institution), ...(cv.experience ?? []).map(x => x.organization)].filter(Boolean);
for (const m of mustExist) {
  if (!src.includes(String(m).toLowerCase().replace(/\s+/g, ' '))) throw new Error('CV_STRUCTURE_NOT_IN_SOURCE: ' + m);
}
return [{ json: { ...base, cv_data: cv } }];
